
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_rtpss_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_rtpss", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.765594289454719e+00, -4.669190077794404e+00, -4.534073690310441e+00, -4.346846077666428e+00, -4.091627316416346e+00, -3.751838103251604e+00, -3.314636179133039e+00, -2.779798228853410e+00, -2.175722536931733e+00, -1.579919057432668e+00, -1.058899735174969e+00, -6.948591266858487e-01, -6.017762200584353e-01, -5.137455254066972e-01, -3.707448779903896e-01, -2.401189633446469e-01, -1.443922985050115e-01, -5.042689669988915e-02, -1.082147707426292e-02, -1.216216050001396e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


